const q=document.querySelector('#query'),b=document.querySelector('#searchBtn'),out=document.querySelector('#results'),stats=document.querySelector('#stats'),count=document.querySelector('#count'),hint=document.querySelector('#hint');let mode='username';
document.querySelectorAll('.tab').forEach(t=>t.onclick=()=>{document.querySelectorAll('.tab').forEach(x=>x.classList.remove('active'));t.classList.add('active');mode=t.dataset.mode;q.placeholder=mode==='username'?'Entre un pseudo, ex. Karl_123':'Entre un domaine, ex. example.com';hint.textContent=mode==='username'?'Les profils proposÃ©s sont des candidats : vÃ©rifie toujours la source.':'Les rÃ©sultats sont des ressources publiques liÃ©es au domaine.';q.focus()});
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));
function render(items){out.innerHTML='';if(!items.length){out.innerHTML='<div class="empty">Aucun rÃ©sultat retournÃ©.</div>';return}items.forEach((x,i)=>{const e=document.createElement('article');e.className='result';e.style.animationDelay=Math.min(i*35,400)+'ms';e.innerHTML=`<div class="resulttop"><span class="source">${esc(x.source)}</span><span class="kind">${esc(x.kind)}</span></div><h3>${esc(x.title)}</h3><p>${esc(x.description||'Source publique.')}</p><a href="${esc(x.url)}" target="_blank" rel="noopener noreferrer">Ouvrir la source â†—</a>`;out.appendChild(e)})}
async function search(){let v=q.value.trim();if(!v)return q.focus();b.disabled=true;b.textContent='Rechercheâ€¦';out.innerHTML='<div class="loading">Analyse des sources publiquesâ€¦</div>';stats.hidden=true;try{let r=await fetch(mode==='username'?'https://kar-osint.onrender.com/api/search/username':'https://kar-osint.onrender.com/api/search/domain',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(mode==='username'?{username:v}:{domain:v})});let d=await r.json();if(!r.ok||!d.ok)throw Error(d.error||'Erreur');count.textContent=d.count;stats.hidden=false;render(d.results)}catch(e){out.innerHTML=`<div class="error">${esc(e.message)}</div>`}finally{b.disabled=false;b.textContent='âŒ• Rechercher'}}b.onclick=search;q.onkeydown=e=>{if(e.key==='Enter')search()};

